  "quiz": [
    {
      "id": "q1",
      "q": "长廊画像里那位倚着钟楼外廊的白衣女子是谁？",
      "options": [
        {
          "key": "A",
          "text": "德国工程师韦伯的夫人"
        },
        {
          "key": "B",
          "text": "甄鹤年的原配夫人白素秋"
        },
        {
          "key": "C",
          "text": "张守业的生母"
        },
        {
          "key": "D",
          "text": "蓉晚棠的生母"
        }
      ],
      "answer": "B",
      "clue": "zt_gal_1",
      "explain": "画框下的铜牌写着白素秋、民国九年；她是甄鹤年的原配，十五年前从钟楼外廊坠下中庭。"
    },
    {
      "id": "q2",
      "q": "白夫人出事之后，被甄家以失职为由辞退、带着儿子离堡的是谁？",
      "options": [
        {
          "key": "A",
          "text": "园丁"
        },
        {
          "key": "B",
          "text": "厨娘"
        },
        {
          "key": "C",
          "text": "敲钟人撒老钟"
        },
        {
          "key": "D",
          "text": "司机"
        }
      ],
      "answer": "C",
      "clue": "zt_chapel_4",
      "explain": "礼拜堂神父的登记簿里，白素秋安葬的下一行写着：敲钟人撒老钟，因失职辞退，携子离堡。"
    },
    {
      "id": "q3",
      "q": "十五年前，何慎之在白夫人的文书上最后写下的是什么？",
      "options": [
        {
          "key": "A",
          "text": "失足坠楼"
        },
        {
          "key": "B",
          "text": "心疾猝发"
        },
        {
          "key": "C",
          "text": "投崖自尽"
        },
        {
          "key": "D",
          "text": "风寒不治"
        }
      ],
      "answer": "A",
      "clue": "zt_he_3",
      "explain": "何慎之客房脸盆里没烧尽的纸角，印着德华医院的抬头，残留着失足坠楼几个字。"
    },
    {
      "id": "q4",
      "q": "蓉晚棠嫁进鸦鸣堡，是因为什么？",
      "options": [
        {
          "key": "A",
          "text": "父亲欠下甄鹤年的债，以女抵债"
        },
        {
          "key": "B",
          "text": "戏班把她卖给了甄家"
        },
        {
          "key": "C",
          "text": "甄鹤年救过她的命"
        },
        {
          "key": "D",
          "text": "替姐姐出嫁"
        }
      ],
      "answer": "A",
      "clue": "zt_rong_4",
      "explain": "妆台夹层里的借据抄件：蓉父欠甄鹤年三万银元，下方红笔写着以女抵债，两清。"
    },
    {
      "id": "q5",
      "q": "张守业挪用矿务公司的款子，大半填进了哪里？",
      "options": [
        {
          "key": "A",
          "text": "买下了青岛的一栋洋房"
        },
        {
          "key": "B",
          "text": "青岛跑马厅俱乐部的赌账"
        },
        {
          "key": "C",
          "text": "捐给了报馆"
        },
        {
          "key": "D",
          "text": "寄回了老家"
        }
      ],
      "answer": "B",
      "clue": "zt_zhang_4",
      "explain": "皮箱夹层里的当票、跑马厅俱乐部的筹码，和涂改过的支票存根放在一起。"
    },
    {
      "id": "q6",
      "q": "白素秋生前最后想送到报馆去的，是什么事？",
      "options": [
        {
          "key": "A",
          "text": "甄家的家产账"
        },
        {
          "key": "B",
          "text": "矿上四十条人命的账"
        },
        {
          "key": "C",
          "text": "德国工程师的遗嘱"
        },
        {
          "key": "D",
          "text": "欧玉芬的身世"
        }
      ],
      "answer": "B",
      "clue": "zt_ou_4",
      "explain": "欧玉芬床板夹层里白素秋的日记，最后一页写着要把矿上四十条人命的账送去报馆。"
    }
  ],
